L2.alley=()=>{const C=Cam({vx:960,PH:470});let bg=sky('#1a1a2a','#3a3a5a',C.Hz)+ground(C,'#2a2a32');
 bg+=box(C,{x0:-30,x1:-2.6,y0:0,y1:14,z0:1,z1:40},{front:'#5a3a3a',side:'#6a4040'})+box(C,{x0:2.6,x1:30,y0:0,y1:14,z0:1,z1:40},{front:'#4a3a4a',side:'#5a4050'});
 for(let z=2;z<38;z+=.6) for(let y=0;y<13;y+=.4){if(rnd()<.35){bg+=rectSide(C,-2.6,z,z+.55,y,y+.35,'#6a4444',L,.4);}}
 bg+=box(C,{x0:-2.5,x1:-1.4,y0:0,y1:1.2,z0:7,z1:8.6},{front:'#3a6a4a'})+box(C,{x0:1.6,x1:2.5,y0:0,y1:.9,z0:10,z1:11},{front:'#5a5a66'})+rectSide(C,2.6,5,6.6,1,2.6,'#ff5fa8')+glow(...C.P(2.6,1.8,5.8),300,'#ff5fa8',.4)+line(C.P(-2.6,4,3),C.P(2.6,4,9),'#1a1a22',3)+lamp(C,2.4,14,true);
 return R({C,bg,spots:[[-.7,4.6],[.7,4.8]],rim:'#ff8ad8',grade:['#8a8aff',.7,'#1a0a2a',.25]});};
L2.moon=()=>{const C=Cam({vx:960,PH:470});let bg=`<rect width="${W}" height="${H}" fill="#06061a"/>`+stars(200,H);
 bg+=`<circle cx="1500" cy="220" r="110" fill="#4a8ad8"/><path d="M1440,180 q40,-30 70,0 q-20,40 -60,30Z M1500,260 q30,-20 60,10 q-30,20 -60,-10Z" fill="#5aa86a"/>`+glow(1500,220,300,'#8ab0ff',.4);
 bg+=ground(C,'#a8a8b0');for(let i=0;i<20;i++){const [x,y]=C.P((rnd()-.5)*30,0,3+rnd()*30);const r=(10+rnd()*40)*C.k(10);bg+=`<ellipse cx="${f(x)}" cy="${f(y)}" rx="${f(r*1.6)}" ry="${f(r*.4)}" fill="#8a8a94" stroke="#7a7a84" stroke-width="2"/>`;}
 bg+=box(C,{x0:3,x1:4.6,y0:0,y1:1.6,z0:9,z1:10.6},{front:'#e8e8ec'})+poly([C.P(3,1.6,9),C.P(4.6,1.6,9),C.P(3.8,2.8,9.8)],'#c8ccd4')+box(C,{x0:-.03,x1:.03,y0:0,y1:2,z0:11,z1:11.06},{front:'#e8e8ec'},{noAO:1})+poly([C.P(.03,2,11),C.P(1,2,11),C.P(1,1.5,11),C.P(.03,1.5,11)],'#e8434f');
 return R({C,bg,spots:[[-.7,5],[.7,5.2]],rim:'#8ab0ff',cast:[1.6,.18],grade:['#8ab0ff',.65,'#0a0a2a']});};
L2.spaceStation=()=>{const [C,b0]=roomBase({RW:3,Zb:12,wall:'#c8d0dc',floor:'#9aa4b4',floorLine:'#7a8494',tiles:.6,ceil:'#b8c0cc'});let bg=b0;
 bg+=winBack(C,12,-2,2,.6,2.4,['#06061a','#1a1a4a',(a,b)=>stars(30,0).replace(/cx="([\d.]+)" cy="([\d.]+)"/g,(m,x,y)=>`cx="${f(a[0]+(+x/W)*(b[0]-a[0]))}" cy="${f(a[1]+rnd()*(b[1]-a[1]))}"`)+`<circle cx="${f(b[0]-60)}" cy="${f(b[1]-40)}" r="60" fill="#4a8ad8"/>`],'#8a94a4');
 for(let z=2;z<12;z+=1.4){bg+=rectSide(C,-3,z,z+1.2,.6,2.2,'#a8b0bc')+rectSide(C,3,z,z+1.2,.6,2.2,'#a8b0bc');bg+=[...Array(3)].map((_,i)=>rectSide(C,-2.99,z+.2+i*.3,z+.4+i*.3,1.6,1.7,pc(i+Math.floor(z)),L,.8)).join('');}
 bg+=glow(...C.P(0,1.5,12),500,'#8ab0ff',.3);
 return R({C,bg,spots:[[-.6,4.6],[.6,4.8]],rim:'#8ab0ff',grade:['#c0d8ff',.5,'#1a2a4a']});};

module.exports={L2};
